/* @lc app=leetcode id=3224 lang=kotlin */ class Solution { fun minChanges(nums: IntArray, k: Int): Int = (nums.size / 2).let { P -> IntArray(k + 2).let { cd -> IntArray(k + 2).let { rc -> (0 until P).forEach { i -> nums[i].let { a -> nums[nums.size - 1 - i].let { b -> cd[Math.abs(a - b)]++.let { rc[0]++ }.let { rc[maxOf(a, b, k - minOf(a, b)) + 1]-- } } } }.let { rc.runningFold(0) { s, v -> s + v }.drop(1).let { reach -> (0..k).minOf { 2 * P - reach[it] - cd[it] } } } } } } }